"""Original monthly retrieval practice. Stable note refs, deterministic option rotation."""
import json,pathlib,random
R=pathlib.Path(__file__).resolve().parents[1]
def make(month,rows):
 Q=[]
 for ref,text,correct,wrongs,explanation in rows:
  opts=[correct]+wrongs.split('|');assert len(opts)==4
  random.Random(month+str(len(Q))).shuffle(opts)
  Q.append(dict(id=month[:3].upper()+f'-{len(Q)+1:02}',question=text,options=opts,answer=opts.index(correct),explanation=explanation,ref=ref if isinstance(ref,str) else 'E5-250'+{'june':'6','july':'7','august':'8'}[month]+f'-{ref:03}'))
 assert len(Q)==30
 (R/'data'/f'{month}-mcqs.json').write_text(json.dumps(Q,ensure_ascii=False,indent=2))
